+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.core.ui.ApplicationErrorView;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.welcome.ui.WelcomeView;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H2;
+import com.vaadin.flow.component.sidenav.SideNavItem;
+import com.vaadin.flow.data.provider.Query;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import java.util.List;
+
+import static ai.unifiedprocess.demo.petclinic.database.tables.VetSpecialties.VET_SPECIALTIES;
+import static ai.unifiedprocess.demo.petclinic.database.tables.Vets.VETS;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+/** UC-002: veterinarian directory, including lazy data access and failure rendering. */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-002", "BR-003"})
+    void navigationOpensDirectoryWithNamesAndOrderedSpecialties() {
+        navigate(WelcomeView.class);
+        SideNavItem link = assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Expected the veterinarian navigation link");
+        UI.getCurrent().navigate(link.getPath());
+
+        Grid<Vet> grid = grid();
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        assertEquals(6, test(grid).size());
+        assertEquals("First Name", test(grid).getHeaderCell(0));
+        assertEquals("Last Name", test(grid).getHeaderCell(1));
+        assertEquals("Specialties", test(grid).getHeaderCell(2));
+        assertEquals("James", test(grid).getCellText(0, 0));
+        assertEquals("Carter", test(grid).getCellText(0, 1));
+        assertEquals("none", test(grid).getCellText(0, 2));
+        assertEquals("Linda", test(grid).getCellText(1, 0));
+        assertEquals("Douglas", test(grid).getCellText(1, 1));
+        assertEquals("dentistry, surgery", test(grid).getCellText(1, 2));
+        assertEquals("radiology", test(grid).getCellText(3, 2));
+        assertEquals(6, dsl.fetchCount(VETS), "Browsing must leave the data unchanged");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void lazyProviderFetchesBoundedDistinctChunksUntilTheEnd() {
+        for (int index = 0; index < 120; index++) {
+            dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                    .values("Additional", "Vet%03d".formatted(index)).execute();
+        }
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        assertFalse(grid.getDataProvider().isInMemory(), "Directory must fetch lazily");
+        assertEquals(126, test(grid).size());
+
+        List<Vet> first = page(grid, 0, 40);
+        List<Vet> next = page(grid, 40, 40);
+        List<Vet> third = page(grid, 80, 40);
+        List<Vet> last = page(grid, 120, 40);
+        assertEquals(40, first.size());
+        assertEquals(40, next.size());
+        assertEquals(40, third.size());
+        assertEquals(6, last.size());
+        assertEquals(126, java.util.stream.Stream.of(first, next, third, last)
+                .flatMap(List::stream).map(Vet::id).distinct().count());
+        assertEquals("Vet033", first.getLast().lastName());
+        assertEquals("Vet034", next.getFirst().lastName());
+        assertTrue(page(grid, 126, 40).isEmpty());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyClinicRendersGridWithoutRows() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+        navigate(VetsView.class);
+
+        Grid<Vet> grid = grid();
+        assertEquals(0, test(grid).size());
+        assertTrue(page(grid, 0, 40).isEmpty());
+        assertDoesNotThrow(() -> find(H2.class).withText("Veterinarians").single(),
+                "Expected the directory heading even when no veterinarians exist");
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void dataAccessFailureReplacesDirectoryWithApplicationErrorView() {
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        dsl.dropTable(VET_SPECIALTIES).execute();
+
+        assertTrue(page(grid, 0, 40).isEmpty());
+        assertDoesNotThrow(() -> find(ApplicationErrorView.class).single(),
+                "Expected application error view after a lazy fetch fails");
+        assertTrue(find(Grid.class).all().isEmpty(), "Failed directory must not remain visible");
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void countFailureReplacesDirectoryWithApplicationErrorView() {
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        dsl.dropTable(VET_SPECIALTIES).execute();
+        dsl.dropTable(VETS).execute();
+
+        assertEquals(0, grid.getDataProvider().size(new Query<>()));
+        assertDoesNotThrow(() -> find(ApplicationErrorView.class).single(),
+                "Expected application error view when the directory count fails");
+        assertTrue(find(Grid.class).all().isEmpty(), "Failed directory must not remain visible");
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Vet> grid() {
+        return assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected exactly one veterinarian grid");
+    }
+
+    private List<Vet> page(Grid<Vet> grid, int offset, int limit) {
+        return grid.getDataProvider().fetch(new Query<>(offset, limit, List.of(), null, null)).toList();
+    }
+}
